{"batchcomplete":true,"query":{"pages":[{"pageid":571,"ns":0,"title":"Artes culinarias/Recetas/Arroz al vino","revisions":[{"revid":417303,"parentid":209886,"user":"Mazbel","timestamp":"2024-07-25T02:39:05Z","slots":{"main":{"contentmodel":"wikitext","contentformat":"text/x-wiki","content":"{{Artes culinarias/Datos de receta
